 "content": "from collections import Counter

def _components(g, color):
    h, w = len(g), len(g[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            if g[r][c] != color or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==color:
                        seen.add(p); q.append(p)
            out.append(cells)
    return out

def _shape(cells):
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def _l_corner(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    # A marker is a clean, one-cell-wide L with arms meeting at one corner.
    for cr in (r0,r1):
        for cc in (c0,c1):
            expected={(cr,c) for c in range(c0,c1+1)} | {(r,cc) for r in range(r0,r1+1)}
            if set(cells)==expected and len(expected)>=6:
                return cr,cc,r0,r1,c0,c1
    return None

def transform(grid):
    h,w=len(grid),len(grid[0]); colors=set(v for row in grid for v in row)
    comps={color:_components(grid,color) for color in colors}
    for marker, marker_comps in comps.items():
        for lcomp in marker_comps:
            corner=_l_corner(lcomp)
            if not corner: continue
            cr,cc,r0,r1,c0,c1=corner
            # Object in the quadrant opposite the L elbow, within its bounding box.
            ref_candidates=[]
            for color, objects in comps.items():
                if color==marker: continue
                for obj in objects:
                    if all(r0<=r<=r1 and c0<=c<=c1 for r,c in obj) and all((r,c) not in lcomp for r,c in obj):
                        if all((r-cr)*(cr-r0 if cr==r1 else r1-cr)>=0 for r,c in []): pass
                        # Strictly toward the diagonally opposite corner.
                        if ((cr==r0 and all(r>cr for r,c in obj)) or (cr==r1 and all(r<cr for r,c in obj))) and ((cc==c0 and all(c>cc for r,c in obj)) or (cc==c1 and all(c<cc for r,c in obj))):
                            ref_candidates.append((color,obj))
            for ref_color, ref in ref_candidates:
                shape=_shape(ref)
                copies=[]
                for color, objects in comps.items():
                    if color==marker: continue
                    for obj in objects:
                        if obj is ref or _shape(obj)!=shape: continue
                        # Duplicate must lie outside marker's bounding box.
                        if not any(r0<=r<=r1 and c0<=c<=c1 for r,c in obj):
                            copies.append((color,obj))
                if copies:
                    # One matching copy is the target; prefer a different color from the reference.
                    copies.sort(key=lambda item: (item[0]==ref_color, min(r for r,c in item[1]), min(c for r,c in item[1])))
                    out=[row[:] for row in grid]
                    for r,c in copies[0][1]: out[r][c]=marker
                    return out
    return [row[:] for row in grid]
